oxy_webhelp_navlinks = {"sass_reporting-d39307e43764":{"topics":[{"title":"SaaS application report templates table","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span>provides a template for each report category. You can use default         reports as basic templates and modify them to create new reports. The following table         describes the available report template types.<\/p>","href":"common\/saas_report_templates.html","attributes":{"data-id":"saas_report_templates"},"menu":{"hasChildren":false},"tocID":"saas_report_templates-d39307e43775","topics":[]},{"title":"Creating reports for SaaS applications","shortdesc":"<p class=\"shortdesc\">Create reports for SaaS applications to view information in your application, such as         compliance status and protection status, using the available templates, which you can         customize for each report type. You can use the data gathered in the reports to perform         audits and data management planning.<\/p>","href":"common\/saas_creating_reports_instances.html","attributes":{"data-id":"saas_creating_reports_instances"},"menu":{"hasChildren":false},"tocID":"saas_creating_reports_instances-d39307e43788","topics":[]}]}};